<template>
  <section class="channel-music" data-ws-part="voice.music" :aria-label="mt('title')">
    <header class="music-summary">
      <div class="music-cover" aria-hidden="true"><img v-if="status?.artwork" :src="status.artwork" alt="" referrerpolicy="no-referrer"/><Icon v-else name="music" :size="22"/></div>
      <div class="music-now"><h3>{{ mt('title') }}</h3><strong>{{ status?.title || mt('waiting') }}</strong><span>{{ status?.artist || mt('shared') }}</span></div>
      <div class="music-transport">
        <button :disabled="!canControl || busy" :aria-label="mt('previous')" :title="mt('previous')" @click="perform('control',{control:'previous'})"><Icon name="previous" :size="17"/></button>
        <button class="music-play" :disabled="!canControl || busy" :aria-label="mt(status?.state === 'playing' ? 'pause' : 'play')" :title="mt(status?.state === 'playing' ? 'pause' : 'play')" @click="perform('control',{control:status?.state === 'playing' ? 'pause' : 'play'})"><Icon :name="status?.state === 'playing' ? 'pause' : 'play'" :size="20"/></button>
        <button :disabled="!canControl || busy" :aria-label="mt('next')" :title="mt('next')" @click="perform('control',{control:'next'})"><Icon name="next" :size="17"/></button>
      </div>
      <button class="music-expand" :aria-expanded="open" :aria-label="mt(open?'close':'open')" @click="open=!open"><Icon name="search" :size="17"/><span>{{ mt(open?'close':'open') }}</span></button>
    </header>
    <div v-if="status?.duration" class="music-progress"><progress :value="status.elapsed" :max="status.duration" :aria-label="status.title"></progress><span>{{ duration(status.elapsed) }} / {{ duration(status.duration) }}</span></div>
    <div v-if="open" class="music-browser" data-ws-part="voice.music.browser">
      <p class="music-channel-note">{{ mt('shared') }}</p>
      <p v-if="!result && !error" role="status">{{ mt('loading') }}</p>
      <p v-else-if="result && !result.enabled">{{ mt('unconfigured') }}</p>
      <div v-else-if="result && !result.inChannel" class="music-channel-missing"><p>{{ mt('otherChannel') }}</p><button v-if="result.botChannelId" @click="emit('joinChannel',result.botChannelId)">{{ mt('join') }}</button></div>
      <p v-if="error" class="music-error" role="alert">{{ musicErrorText(language,error) }} <button :disabled="busy" @click="error=''; refresh()">{{ mt('refresh') }}</button></p>
      <template v-if="canControl">
        <div class="music-tabs" role="tablist" :aria-label="mt('title')"><button v-for="name in tabs" :id="`music-tab-${name}`" :key="name" role="tab" :tabindex="tab===name?0:-1" :aria-selected="tab===name" :aria-controls="`music-content-${name}`" @keydown="tabKey($event,name)" @click="selectTab(name)">{{ mt(name) }}<span v-if="name==='queue'">{{ result?.total ?? queue.length }}</span></button></div>
        <div class="music-options">
          <label>{{ mt('volume') }}<input type="range" min="0" max="100" :value="Math.min(status?.volume??100,100)" :disabled="busy" @change="perform('volume',{volume:Number(($event.target as HTMLInputElement).value)})"/></label>
          <button :disabled="busy" :aria-pressed="status?.shuffled ?? false" @click="perform('shuffle',{enabled:!status?.shuffled})">{{ mt('shuffle') }}</button>
          <label>{{ mt('repeat') }}<select :disabled="busy" :value="status?.repeat??'none'" @change="perform('repeat',{mode:($event.target as HTMLSelectElement).value as 'none'|'all'|'one'})"><option value="none">{{ mt('repeatNone') }}</option><option value="all">{{ mt('repeatAll') }}</option><option value="one">{{ mt('repeatOne') }}</option></select></label>
        </div>
        <div :id="`music-content-${tab}`" role="tabpanel" :aria-labelledby="`music-tab-${tab}`">
          <form v-if="tab==='search'" class="music-search" @submit.prevent="search()"><select v-model="source" :aria-label="mt('search')"><option value="netease">网易云音乐</option><option value="qqmusic">QQ 音乐</option><option value="bilibili">Bilibili</option></select><input v-model="keywords" type="search" maxlength="120" :placeholder="mt('placeholder')" :aria-label="mt('placeholder')"/><button :disabled="loading||busy||!keywords.trim()" type="submit"><Icon name="search" :size="16"/><span>{{ mt('search') }}</span></button></form>
          <template v-if="tab==='playlists'">
            <form class="music-search music-playlist-form" @submit.prevent="loadPlaylist()"><select v-model="source" :aria-label="mt('playlists')"><option value="netease">网易云音乐</option><option value="qqmusic">QQ 音乐</option></select><input v-model="playlistInput" maxlength="2048" :placeholder="mt('playlistPlaceholder')" :aria-label="mt('playlistPlaceholder')"/><button type="submit" :disabled="loading||busy||!playlistInput.trim()">{{ mt('load') }}</button></form>
            <div v-if="saved.length" class="music-saved"><span>{{ mt('saved') }}</span><div v-for="record in saved" :key="`${record.source}:${record.id}`"><button :disabled="loading||busy" @click="loadPlaylist(record.id,record.source)">{{ record.name }} <small>{{ record.source==='netease'?'网易云':'QQ' }}</small></button><button :aria-label="mt('forget')" :title="mt('forget')" @click="forgetPlaylist(record)"><Icon name="close" :size="14"/></button></div></div>
            <div v-if="playlistName" class="music-playlist-heading"><div><strong>{{ playlistName }}</strong><span>{{ items.length }} / {{ playlistTotal }}</span></div><button :disabled="busy||loading||!items.length" @click="enqueueAll(true)"><Icon name="play" :size="15"/>{{ mt('playPlaylist') }}</button><button :disabled="busy||loading||!items.length" @click="enqueueAll(false)"><Icon name="plus" :size="15"/>{{ mt('addPlaylist') }}</button></div>
            <p v-if="playlistName" class="music-footnote">{{ mt('playlistLimit') }}</p>
          </template>
          <p v-if="loading" role="status">{{ mt('loading') }}</p>
          <p v-else-if="!displayItems.length" class="music-empty">{{ mt(tab==='queue'?'emptyQueue':tab==='playlists'?'emptyPlaylist':'emptySearch') }}</p>
          <ol v-else class="music-results" :aria-label="mt(tab==='queue'?'queue':tab==='playlists'?'playlists':'search')">
            <li v-for="(track,index) in displayItems" :key="`${track.source}:${track.queueId??track.id}`"><span class="music-index">{{ index+1 }}</span><div class="music-track"><strong :title="track.title">{{ track.title }}</strong><span :title="track.artist">{{ track.artist || track.album }}<small>{{ sourceLabel(track.source) }}</small></span></div><span class="music-duration">{{ duration(track.duration) }}</span><button :disabled="busy" :aria-label="`${mt('playNow')}: ${track.title}`" :title="mt('playNow')" @click="perform(tab==='queue'?'queuePlay':'enqueue',tab==='queue'?{queueId:track.queueId}:{source:track.source,id:track.id,playNow:true})"><Icon name="play" :size="17"/></button><button :disabled="busy" :aria-label="`${mt(tab==='queue'?'remove':'add')}: ${track.title}`" :title="mt(tab==='queue'?'remove':'add')" @click="perform(tab==='queue'?'remove':'enqueue',tab==='queue'?{queueId:track.queueId}:{source:track.source,id:track.id,playNow:false})"><Icon :name="tab==='queue'?'close':'plus'" :size="17"/></button></li>
          </ol>
          <div v-if="tab==='search'&&(page>1||hasMore)" class="music-pages"><button :disabled="loading||page===1" @click="search(page-1)">{{ mt('previousPage') }}</button><span>{{ page }}</span><button :disabled="loading||!hasMore" @click="search(page+1)">{{ mt('nextPage') }}</button></div>
          <div v-if="tab==='playlists'&&playlistName&&(page>1||hasMore)" class="music-pages"><button :disabled="busy||loading||page===1" @click="playlistPage(page-1)">{{ mt('previousPage') }}</button><span>{{ page }}</span><button :disabled="busy||loading||!hasMore" @click="playlistPage(page+1)">{{ mt('nextPage') }}</button></div>
        </div>
        <div v-if="batch.total" class="music-batch" role="status"><span>{{ mt('batchProgress') }} {{ batch.completed }} / {{ batch.failed }} · {{ batch.total }}</span><button v-if="batch.active" @click="stopBatch">{{ mt('stopBatch') }}</button></div>
        <p v-if="notice" class="music-notice" role="status">{{ mt(notice as 'queued'|'trial'|'storageUnavailable'|'batchComplete') }}</p>
      </template>
    </div>
  </section>
</template>
<script setup lang="ts">
import { computed, nextTick } from "vue";
import Icon from "../Icon.vue";
import { musicText, musicErrorText } from "../../i18n/music.js";
import type { useWebClientMusic } from "../../composables/useWebClientMusic.js";
import type { MusicSource } from "../../../../src/shared/music.js";
const props=defineProps<{model:ReturnType<typeof useWebClientMusic>;language:string}>();
const open=defineModel<boolean>("open",{required:true});
const emit=defineEmits<{joinChannel:[id:string]}>();
const {source,keywords,tab,result,items,queue,status,saved,canControl,loading,busy,error,notice,page,hasMore,playlistInput,playlistName,playlistTotal,batch,refresh,search,loadPlaylist,forgetPlaylist,perform,enqueueAll,stopBatch,playlistPage,cancelBrowse}=props.model;
const mt=(key:Parameters<typeof musicText>[1])=>musicText(props.language,key);
const displayItems=computed(()=>tab.value==='queue'?queue.value:items.value);
const tabs=['search','queue','playlists'] as const;
function selectTab(next:typeof tab.value){if(next===tab.value)return;cancelBrowse();tab.value=next;if(next==='search'||next==='playlists'){items.value=[];playlistName.value='';page.value=1;hasMore.value=false;}if(next==='playlists'&&source.value==='bilibili')source.value='netease';if(next==='queue')void refresh();}
function tabKey(event:KeyboardEvent,name:typeof tab.value){
  const index=tabs.indexOf(name);let next:number;
  if(event.key==='ArrowRight')next=(index+1)%tabs.length;
  else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;
  else if(event.key==='Home')next=0;
  else if(event.key==='End')next=tabs.length-1;
  else return;
  event.preventDefault();selectTab(tabs[next]!);void nextTick(()=>document.getElementById(`music-tab-${tabs[next]}`)?.focus());
}
function duration(seconds:number){const s=Math.floor(Math.max(0,seconds));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
function sourceLabel(value:MusicSource){return value==='netease'?'网易云':value==='qqmusic'?'QQ':'Bilibili';}
</script>
<style scoped>
.channel-music{--music-muted:color-mix(in srgb,var(--text-primary,#213547) 82%,var(--surface-1,#fff));margin-top:22px;border:1px solid var(--border,#d5dfe2);border-radius:12px;background:var(--surface-1,#fff);color:var(--text-primary,#213547);overflow:hidden;min-width:0}
.music-summary{display:flex;align-items:center;gap:12px;padding:15px 16px}.music-cover{width:48px;height:48px;display:grid;place-items:center;background:var(--surface-2,#edf4f3);border-radius:8px;flex:0 0 auto;overflow:hidden}.music-cover img{width:100%;height:100%;object-fit:cover}.music-now{display:grid;gap:3px;flex:1;min-width:0}.music-now h3{font-size:12px;margin:0;font-weight:600;color:var(--music-muted,#54616c)}.music-now strong{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.music-now>span{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--music-muted,#54616c)}
.channel-music button,.channel-music select,.channel-music input{font:inherit;color:inherit}.channel-music button{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:7px 9px;border:1px solid var(--border,#d5dfe2);border-radius:7px;background:transparent;cursor:pointer}.channel-music button:hover:not(:disabled){background:var(--surface-2,#edf4f3)}.channel-music button:disabled{opacity:.45;cursor:default}.channel-music :is(button,select,input):focus-visible{outline:2px solid var(--accent,#006a64);outline-offset:3px}.music-transport{display:flex;align-items:center;gap:5px}.music-transport button{border:0;min-width:34px}.music-transport .music-play{color:var(--accent,#006a64);background:var(--surface-2,#edf4f3);width:40px;height:40px}.music-expand{flex:0 0 auto;font-size:12px!important}.music-progress{display:flex;align-items:center;gap:10px;padding:0 16px 12px}.music-progress progress{width:100%;height:4px;accent-color:var(--accent,#006a64)}.music-progress span{white-space:nowrap;font-size:11px;font-variant-numeric:tabular-nums}.music-browser{padding:0 16px 16px}.music-channel-note{margin:0 0 14px;font-size:12px;color:var(--music-muted,#54616c)}.music-tabs{display:flex;gap:18px;border-bottom:1px solid var(--border,#d5dfe2);margin-bottom:14px}.music-tabs button{border:0;border-radius:0;padding:8px 0 10px;font-size:13px}.music-tabs button[aria-selected=true]{color:var(--accent,#006a64);box-shadow:0 2px 0 var(--accent,#006a64)}.music-tabs span{font-size:11px;background:var(--surface-2,#edf4f3);padding:2px 6px;border-radius:4px}.music-options{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:16px;font-size:12px}.music-options label{display:flex;align-items:center;gap:6px}.music-options input{width:75px;accent-color:var(--accent,#006a64)}.music-options select{max-width:110px}.music-search{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:8px;margin-bottom:14px}.music-search input,.channel-music select{border:1px solid var(--border,#d5dfe2);border-radius:7px;background:var(--surface-1,#fff);padding:9px;min-width:0;font-size:13px}.music-search input::placeholder{color:var(--music-muted,#54616c)}.music-search input{caret-color:var(--accent,#006a64)}.music-empty{padding:26px 0;text-align:center;font-size:13px;color:var(--music-muted,#54616c)}.music-results{list-style:none;margin:0;padding:0;max-height:320px;overflow:auto;scrollbar-width:thin;scrollbar-color:var(--border,#bacccc) transparent}.music-results li{display:flex;gap:9px;align-items:center;padding:8px 0;border-bottom:1px solid var(--border,#e5ebeb)}.music-index{width:20px;text-align:right;flex:0 0 auto;color:var(--music-muted,#54616c);font-size:11px;font-variant-numeric:tabular-nums}.music-track{flex:1;min-width:0;display:grid;gap:4px}.music-track strong{font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.music-track>span{font-size:12px;color:var(--music-muted,#54616c);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.music-track small{font-size:10px;margin-left:8px}.music-duration{font-size:11px;font-variant-numeric:tabular-nums;color:var(--music-muted,#54616c)}.music-results button{border:0;min-width:34px}.music-pages,.music-batch{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:14px;font-size:12px}.music-error{color:var(--danger,#a53131);font-size:13px}.music-error button{font-size:12px;margin-left:6px}.music-notice{font-size:12px;color:var(--accent,#006a64);margin-bottom:0}.music-saved{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:16px}.music-saved>span{width:100%;color:var(--music-muted,#54616c);font-size:11px}.music-saved>div{display:flex;align-items:center;max-width:100%}.music-saved>div>button:first-child{max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.music-saved small{color:var(--music-muted,#54616c);font-size:10px}.music-saved>div>button:last-child{border:0;min-width:28px;padding:4px}.music-playlist-heading{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:20px;margin-bottom:8px}.music-playlist-heading>div{display:flex;gap:8px;align-items:center;min-width:0;flex:1 1 160px}.music-playlist-heading strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px}.music-playlist-heading span{font-size:11px;white-space:nowrap;color:var(--music-muted,#54616c)}.music-playlist-heading button{font-size:12px}.music-footnote{font-size:11px;line-height:1.6;color:var(--music-muted,#54616c);margin:4px 0 14px}.channel-music ::selection{background:var(--accent,#006a64);color:white}
@media(max-width:600px){.music-summary{gap:8px;padding:12px}.music-cover{width:38px;height:38px}.music-now h3{font-size:11px}.music-transport{gap:0}.music-transport button{min-width:30px;padding:5px}.music-transport .music-play{width:36px;height:36px}.music-expand span{display:none}.music-browser{padding:0 12px 12px}.music-summary .music-expand{min-width:40px;min-height:44px}.music-search{grid-template-columns:minmax(0,1fr) auto}.music-search select{grid-column:1/-1}.music-search input{font-size:16px}.channel-music button{min-height:44px}.music-results button{min-width:38px}.music-duration{display:none}.music-options{gap:8px}.music-options label:first-child{width:100%;justify-content:space-between}.music-options input{flex:1;max-width:160px}.music-tabs{gap:20px}.music-results{max-height:300px}}
</style>
